export default JSON.parse(
  "{\n  \"workId\": \"xunzi\",\n  \"chapter\": {\n    \"id\": \"xunzi_ch-23\",\n    \"workId\": \"xunzi\",\n    \"order\": 23,\n    \"title\": \"性惡\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 13,\n    \"passageIds\": [\n      \"xunzi_ch-23_p-1\",\n      \"xunzi_ch-23_p-2\",\n      \"xunzi_ch-23_p-3\",\n      \"xunzi_ch-23_p-4\",\n      \"xunzi_ch-23_p-5\",\n      \"xunzi_ch-23_p-6\",\n      \"xunzi_ch-23_p-7\",\n      \"xunzi_ch-23_p-8\",\n      \"xunzi_ch-23_p-9\",\n      \"xunzi_ch-23_p-10\",\n      \"xunzi_ch-23_p-11\",\n      \"xunzi_ch-23_p-12\",\n      \"xunzi_ch-23_p-13\",\n      \"xunzi_ch-23_p-14\",\n      \"xunzi_ch-23_p-15\",\n      \"xunzi_ch-23_p-16\",\n      \"xunzi_ch-23_p-17\",\n      \"xunzi_ch-23_p-18\",\n      \"xunzi_ch-23_p-19\",\n      \"xunzi_ch-23_p-20\",\n      \"xunzi_ch-23_p-21\",\n      \"xunzi_ch-23_p-22\",\n      \"xunzi_ch-23_p-23\",\n      \"xunzi_ch-23_p-24\"\n    ],\n    \"tags\": [\n      \"儒家\",\n      \"性惡論\",\n      \"禮樂\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"xunzi_ch-23_p-1\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 1,\n      \"canonicalText\": \"人之性惡，其善者偽也。今人之性，生而有好利焉，順是，故爭奪生而辭讓亡焉；生而有疾惡焉，順是，故殘賊生而忠信亡焉；生而有耳目之欲，有好聲色焉，順是，故淫亂生而禮義文理亡焉。然則從人之性，順人之情，必出於爭奪，合於犯分亂理，而歸於暴。故必將有師法之化，禮義之道，然後出於辭讓，合於文理，而歸於治。用此觀之，人之性惡明矣，其善者偽也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-1_s-1\",\n        \"xunzi_ch-23_p-1_s-2\",\n        \"xunzi_ch-23_p-1_s-3\",\n        \"xunzi_ch-23_p-1_s-4\",\n        \"xunzi_ch-23_p-1_s-5\",\n        \"xunzi_ch-23_p-1_s-6\",\n        \"xunzi_ch-23_p-1_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"人的性惡，他的善的人或事偽啊。今人的性，生而且有好利焉，順是，所以爭奪生而且辭讓亡焉；生而且有疾惡焉，順是，所以殘賊生而且忠信亡焉；生而且有耳目的欲，有好聲色焉，順是，所以淫亂生而且禮道義正道道德行修養規程道義正道文理亡焉。然則從人的性，順人的情，必出於爭奪，合於犯分亂理，而且歸於暴。所以必將有師典章法度的化，禮道義正道道德行修養規程道義正道的道，然後出於辭讓，合於文理，而且歸於治。用此觀的，人的性惡明矣，他的善的人或事偽啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「人之性惡，其善者偽也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「人」、「性」、「惡」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「人之性惡其善者偽也今人之性生而有好利焉順是故爭奪」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「今人之性，生而有好利焉，順是，故爭奪生而辭讓亡焉」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 2,\n      \"canonicalText\": \"故枸木必將待檃栝、烝矯然後直；鈍金必將待礱厲然後利；今人之性惡，必將待師法然後正，得禮義然後治，今人無師法，則偏險而不正；無禮義，則悖亂而不治，古者聖王以人性惡，以為偏險而不正，悖亂而不治，是以為之起禮義，製法度，以矯飾人之情性而正之，以擾化人之情性而導之也，始皆出於治，合於道者也。今人之化師法，積文學，道禮義者為君子；縱性情，安恣睢，而違禮義者為小人。用此觀之，人之性惡明矣，其善者偽也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-2_s-1\",\n        \"xunzi_ch-23_p-2_s-2\",\n        \"xunzi_ch-23_p-2_s-3\",\n        \"xunzi_ch-23_p-2_s-4\",\n        \"xunzi_ch-23_p-2_s-5\",\n        \"xunzi_ch-23_p-2_s-6\",\n        \"xunzi_ch-23_p-2_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以枸木必將待檃栝、烝矯然後直；鈍金必將待礱厲然後利；今人的性惡，必將待師典章法度然後正，得禮道義正道道德行修養規程道義正道然後治，今人無師典章法度，則偏險而且不正；無禮道義正道道德行修養規程道義正道，則悖亂而且不治，古的人或事聖王以人性惡，以為偏險而且不正，悖亂而且不治，是以為的起禮道義正道道德行修養規程道義正道，製典章法度度，以矯飾人的情性而且正的，以擾化人的情性而且導的啊，始皆出於治，合於道的人或事啊。今人的化師典章法度，積文學，道禮道義正道道德行修養規程道義正道的人或事為君子；縱性情，安恣睢，而且違禮道義正道道德行修養規程道義正道的人或事為小人。用此觀的，人的性惡明矣，他的善的人或事偽啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「故枸木必將待檃栝、烝矯然後直」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「枸」、「木」、「必」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故枸木必將待檃栝烝矯然後直鈍金必將待礱厲然後利今」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「鈍金必將待礱厲然後利」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-3\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 3,\n      \"canonicalText\": \"孟子曰：「人之學者，其性善。」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-3_s-1\",\n        \"xunzi_ch-23_p-3_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孟子說道：人的學的人或事，他的性善。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「孟子曰：「人之學者，其性善」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孟」、「子」、「人」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孟子曰人之學者其性善」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「孟子曰：「人之學者，其性善」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 4,\n      \"canonicalText\": \"曰：是不然。是不及知人之性，而不察乎人之性偽之分者也。凡性者，天之就也，不可學，不可事。禮義者，聖人之所生也，人之所學而能，所事而成者也。不可學，不可事，而在人者，謂之性；可學而能，可事而成之在人者，謂之偽。是性偽之分也。今人之性，目可以見，耳可以聽；夫可以見之明不離目，可以聽之聰不離耳，目明而耳聰，不可學明矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-4_s-1\",\n        \"xunzi_ch-23_p-4_s-2\",\n        \"xunzi_ch-23_p-4_s-3\",\n        \"xunzi_ch-23_p-4_s-4\",\n        \"xunzi_ch-23_p-4_s-5\",\n        \"xunzi_ch-23_p-4_s-6\",\n        \"xunzi_ch-23_p-4_s-7\",\n        \"xunzi_ch-23_p-4_s-8\",\n        \"xunzi_ch-23_p-4_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：是不然。是不及知人的性，而且不察乎人的性偽的分的人或事啊。凡性的人或事，天的就啊，不可學，不可事。禮道義正道道德行修養規程道義正道的人或事，聖人的所生啊，人的所學而且能，所事而且成的人或事啊。不可學，不可事，而且在人的人或事，謂的性；可學而且能，可事而且成的在人的人或事，謂的偽。是性偽的分啊。今人的性，目可以見，耳可以聽；夫可以見的明不離目，可以聽的聰不離耳，目明而且耳聰，不可學明矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「曰：是不然」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「是」、「不」、「然」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「曰是不然是不及知人之性而不察乎人之性偽之分者也凡」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「是不及知人之性，而不察乎人之性偽之分者也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-5\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 5,\n      \"canonicalText\": \"孟子曰：「今人之性善，將皆失喪其性故也。」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-5_s-1\",\n        \"xunzi_ch-23_p-5_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孟子說道：今人的性善，將皆失喪他的性所以啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「孟子曰：「今人之性善，將皆失喪其性故也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孟」、「子」、「今」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孟子曰今人之性善將皆失喪其性故也」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「孟子曰：「今人之性善，將皆失喪其性故也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 6,\n      \"canonicalText\": \"曰：若是則過矣。今人之性，生而離其樸，離其資，必失而喪之。用此觀之，然則人之性惡明矣。所謂性善者，不離其樸而美之，不離其資而利之也。使夫資樸之於美，心意之於善，若夫可以見之明不離目，可以聽之聰不離耳，故曰目明而耳聰也。今人之性，飢而欲飽，寒而欲煖，勞而欲休，此人之情性也。今人見長而不敢先食者，將有所讓也；勞而不敢求息者，將有所代也。夫子之讓乎父，弟之讓乎兄，子之代乎父，弟之代乎兄，此二行者，皆反於性而悖於情也；然而孝子之道，禮義之文理也。故順情性則不辭讓矣，辭讓則悖於情性矣。用此觀之，人之性惡明矣，其善者偽也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-6_s-1\",\n        \"xunzi_ch-23_p-6_s-2\",\n        \"xunzi_ch-23_p-6_s-3\",\n        \"xunzi_ch-23_p-6_s-4\",\n        \"xunzi_ch-23_p-6_s-5\",\n        \"xunzi_ch-23_p-6_s-6\",\n        \"xunzi_ch-23_p-6_s-7\",\n        \"xunzi_ch-23_p-6_s-8\",\n        \"xunzi_ch-23_p-6_s-9\",\n        \"xunzi_ch-23_p-6_s-10\",\n        \"xunzi_ch-23_p-6_s-11\",\n        \"xunzi_ch-23_p-6_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：若是則過矣。今人的性，生而且離他的樸，離他的資，必失而且喪的。用此觀的，然則人的性惡明矣。所謂性善的人或事，不離他的樸而且美的，不離他的資而且利的啊。使夫資樸的於美，心意的於善，至於談到那可以見的明不離目，可以聽的聰不離耳，所以說：目明而且耳聰啊。今人的性，飢而且欲飽，寒而且欲煖，勞而且欲休，此人的情性啊。今人見長而且不敢先食的人或事，將有所讓啊；勞而且不敢求息的人或事，將有所代啊。夫子的讓乎父，弟的讓乎兄，子的代乎父，弟的代乎兄，此二行的人或事，皆反於性而且悖於情啊；然而且孝子的道，禮道義正道道德行修養規程道義正道的文理啊。所以順情性則不辭讓矣，辭讓則悖於情性矣。用此觀的，人的性惡明矣，他的善的人或事偽啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「曰：若是則過矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「是」、「過」、「今」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「曰若是則過矣今人之性生而離其樸離其資必失而喪之用」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「今人之性，生而離其樸，離其資，必失而喪之」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-7\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 7,\n      \"canonicalText\": \"問者曰：「人之性惡，則禮義惡生？」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-7_s-1\",\n        \"xunzi_ch-23_p-7_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"問的人或事說道：人的性惡，則禮道義正道道德行修養規程道義正道惡生？\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「問者曰：「人之性惡，則禮義惡生」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「問」、「人」、「性」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「問者曰人之性惡則禮義惡生」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「問者曰：「人之性惡，則禮義惡生」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 8,\n      \"canonicalText\": \"應之曰：凡禮義者，是生於聖人之偽，非故生於人之性也。故陶人埏埴而為器，然則器生於陶人之偽，非故生於人之性也。故工人斲木而成器，然則器生於工人之偽，非故生於人之性也。聖人積思慮，習偽故，以生禮義而起法度，然則禮義法度者，是生於聖人之偽，非故生於人之性也。若夫目好色，耳好聽，口好味，心好利，骨體膚理好愉佚，是皆生於人之情性者也；感而自然，不待事而後生之者也。夫感而不能然，必且待事而後然者，謂之生於偽。是性偽之所生，其不同之徵也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-8_s-1\",\n        \"xunzi_ch-23_p-8_s-2\",\n        \"xunzi_ch-23_p-8_s-3\",\n        \"xunzi_ch-23_p-8_s-4\",\n        \"xunzi_ch-23_p-8_s-5\",\n        \"xunzi_ch-23_p-8_s-6\",\n        \"xunzi_ch-23_p-8_s-7\",\n        \"xunzi_ch-23_p-8_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"應的說道：凡禮道義正道道德行修養規程道義正道的人或事，是生於聖人的偽，絕不是所以生於人的性啊。所以陶人埏埴而且為器，然則器生於陶人的偽，絕不是所以生於人的性啊。所以工人斲木而且成器，然則器生於工人的偽，絕不是所以生於人的性啊。聖人積思慮，習偽所以，以生禮道義正道道德行修養規程道義正道而且起典章法度度，然則禮道義正道道德行修養規程道義正道典章法度度的人或事，是生於聖人的偽，絕不是所以生於人的性啊。至於談到那目好色，耳好聽，口好味，心好利，骨體膚理好愉佚，是皆生於人的情性的人或事啊；感而且自然，不待事而且後生的的人或事啊。夫感而且不能然，必且待事而且後然的人或事，謂的生於偽。是性偽的所生，他的不同的徵啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「應之曰：凡禮義者，是生於聖人之偽，非故生於人之性也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「應」、「凡」、「禮」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「應之曰凡禮義者是生於聖人之偽非故生於人之性也故陶」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故陶人埏埴而為器，然則器生於陶人之偽，非故生於人之性也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 9,\n      \"canonicalText\": \"故聖人化性而起偽，偽起而生禮義，禮義生而製法度；然則禮義法度者，是聖人之所生也。故聖人之所以同於眾，其不異於眾者，性也；所以異而過眾者，偽也。夫好利而欲得者，此人之情性也。假之有弟兄資財而分者，且順情性，好利而欲得，若是，則兄弟相拂奪矣；且化禮義之文理，若是，則讓乎國人矣。故順情性則弟兄爭矣，化禮義則讓乎國人矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-9_s-1\",\n        \"xunzi_ch-23_p-9_s-2\",\n        \"xunzi_ch-23_p-9_s-3\",\n        \"xunzi_ch-23_p-9_s-4\",\n        \"xunzi_ch-23_p-9_s-5\",\n        \"xunzi_ch-23_p-9_s-6\",\n        \"xunzi_ch-23_p-9_s-7\",\n        \"xunzi_ch-23_p-9_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以聖人化性而且起偽，偽起而且生禮道義正道道德行修養規程道義正道，禮道義正道道德行修養規程道義正道生而且製典章法度度；然則禮道義正道道德行修養規程道義正道典章法度度的人或事，是聖人的所生啊。所以聖人的所以同於眾，他的不異於眾的人或事，性啊；所以異而且過眾的人或事，偽啊。夫好利而且欲得的人或事，此人的情性啊。假的有弟兄資財而且分的人或事，且順情性，好利而且欲得，若是，則兄弟相拂奪矣；且化禮道義正道道德行修養規程道義正道的文理，若是，則讓乎國人矣。所以順情性則弟兄爭矣，化禮道義正道道德行修養規程道義正道則讓乎國人矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「故聖人化性而起偽，偽起而生禮義，禮義生而製法度」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「聖」、「人」、「化」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故聖人化性而起偽偽起而生禮義禮義生而製法度然則禮」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「然則禮義法度者，是聖人之所生也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 10,\n      \"canonicalText\": \"凡人之慾為善者，為性惡也。夫薄願厚，惡願美，狹願廣，貧願富，賤願貴，苟無之中者，必求於外。故富而不願財，貴而不願埶，苟有之中者，必不及於外。用此觀之，人之慾為善者，為性惡也。今人之性，固無禮義，故彊學而求有之也；性不知禮義，故思慮而求知之也。然則性而已，則人無禮義，不知禮義。人無禮義則亂，不知禮義則悖。然則性而已，則悖亂在己。用此觀之，人之性惡明矣，其善者偽也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-10_s-1\",\n        \"xunzi_ch-23_p-10_s-2\",\n        \"xunzi_ch-23_p-10_s-3\",\n        \"xunzi_ch-23_p-10_s-4\",\n        \"xunzi_ch-23_p-10_s-5\",\n        \"xunzi_ch-23_p-10_s-6\",\n        \"xunzi_ch-23_p-10_s-7\",\n        \"xunzi_ch-23_p-10_s-8\",\n        \"xunzi_ch-23_p-10_s-9\",\n        \"xunzi_ch-23_p-10_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"凡人的慾為善的人或事，為性惡啊。夫薄願厚，惡願美，狹願廣，貧願富，賤願貴，苟無的中的人或事，必求於外。所以富而且不願財，貴而且不願埶，苟有的中的人或事，必不及於外。用此觀的，人的慾為善的人或事，為性惡啊。今人的性，固無禮道義正道道德行修養規程道義正道，所以彊學而且求有的啊；性不知禮道義正道道德行修養規程道義正道，所以思慮而且求知的啊。然則性而且已，則人無禮道義正道道德行修養規程道義正道，不知禮道義正道道德行修養規程道義正道。人無禮道義正道道德行修養規程道義正道則亂，不知禮道義正道道德行修養規程道義正道則悖。然則性而且已，則悖亂在己。用此觀的，人的性惡明矣，他的善的人或事偽啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「凡人之慾為善者，為性惡也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「凡」、「人」、「慾」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「凡人之慾為善者為性惡也夫薄願厚惡願美狹願廣貧願富」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「夫薄願厚，惡願美，狹願廣，貧願富，賤願貴，苟無之中者，必求於外」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-11\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 11,\n      \"canonicalText\": \"孟子曰：「人之性善。」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-11_s-1\",\n        \"xunzi_ch-23_p-11_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孟子說道：人的性善。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「孟子曰：「人之性善」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「孟」、「子」、「人」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「孟子曰人之性善」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「孟子曰：「人之性善」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 12,\n      \"canonicalText\": \"曰：是不然。凡古今天下之所謂善者，正理平治也；所謂惡者，偏險悖亂也：是善惡之分也矣。今誠以人之性固正理平治邪，則有惡用聖王，惡用禮義哉？雖有聖王禮義，將曷加於正理平治也哉？今不然，人之性惡。故古者聖人以人之性惡，以為偏險而不正，悖亂而不治，故為之立君上之埶以臨之，明禮義以化之，起法正以治之，重刑罰以禁之，使天下皆出於治，合於善也。是聖王之治而禮義之化也。今當試去君上之埶，無禮義之化，去法正之治，無刑罰之禁，倚而觀天下民人之相與也。若是，則夫彊者害弱而奪之，眾者暴寡而譁之，天下悖亂而相亡，不待頃矣。用此觀之，然則人之性惡明矣，其善者偽也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-12_s-1\",\n        \"xunzi_ch-23_p-12_s-2\",\n        \"xunzi_ch-23_p-12_s-3\",\n        \"xunzi_ch-23_p-12_s-4\",\n        \"xunzi_ch-23_p-12_s-5\",\n        \"xunzi_ch-23_p-12_s-6\",\n        \"xunzi_ch-23_p-12_s-7\",\n        \"xunzi_ch-23_p-12_s-8\",\n        \"xunzi_ch-23_p-12_s-9\",\n        \"xunzi_ch-23_p-12_s-10\",\n        \"xunzi_ch-23_p-12_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：是不然。凡古今天下的所謂善的人或事，正理平治啊；所謂惡的人或事，偏險悖亂啊：是善惡的分啊矣。今誠以人的性固正理平治邪，則有惡用聖王，惡用禮道義正道道德行修養規程道義正道哉？雖有聖王禮道義正道道德行修養規程道義正道，將曷加於正理平治啊哉？今不然，人的性惡。所以古的人或事聖人以人的性惡，以為偏險而且不正，悖亂而且不治，所以為的立君上的埶以臨的，明禮道義正道道德行修養規程道義正道以化的，起典章法度正以治的，重刑罰以禁的，使天下皆出於治，合於善啊。是聖王的治而且禮道義正道道德行修養規程道義正道的化啊。今當試去君上的埶，無禮道義正道道德行修養規程道義正道的化，去典章法度正的治，無刑罰的禁，倚而且觀天下民人的相與啊。若是，則夫彊的人或事害弱而且奪的，眾的人或事暴寡而且譁的，天下悖亂而且相亡，不待頃矣。用此觀的，然則人的性惡明矣，他的善的人或事偽啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「曰：是不然」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「是」、「不」、「然」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「曰是不然凡古今天下之所謂善者正理平治也所謂惡者偏」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「凡古今天下之所謂善者，正理平治也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 13,\n      \"canonicalText\": \"故善言古者，必有節於今；善言天者，必有徵於人。凡論者貴其有辨合，有符驗。故坐而言之，起而可設，張而可施行。今孟子曰：「人之性善。」無辨合符驗，坐而言之，起而不可設，張而不可施行，豈不過甚矣哉！故性善則去聖王，息禮義矣。性惡則與聖王，貴禮義矣。故檃栝之生，為枸木也；繩墨之起，為不直也；立君上，明禮義，為性惡也。用此觀之，然則人之性惡明矣，其善者偽也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-13_s-1\",\n        \"xunzi_ch-23_p-13_s-2\",\n        \"xunzi_ch-23_p-13_s-3\",\n        \"xunzi_ch-23_p-13_s-4\",\n        \"xunzi_ch-23_p-13_s-5\",\n        \"xunzi_ch-23_p-13_s-6\",\n        \"xunzi_ch-23_p-13_s-7\",\n        \"xunzi_ch-23_p-13_s-8\",\n        \"xunzi_ch-23_p-13_s-9\",\n        \"xunzi_ch-23_p-13_s-10\",\n        \"xunzi_ch-23_p-13_s-11\",\n        \"xunzi_ch-23_p-13_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以善言古的人或事，必有節於今；善言天的人或事，必有徵於人。凡論的人或事貴他的有辨合，有符驗。所以坐而且言的，起而且可設，張而且可施行。今孟子說道：人的性善。無辨合符驗，坐而且言的，起而且不可設，張而且不可施行，豈不過甚矣哉！所以性善則去聖王，息禮道義正道道德行修養規程道義正道矣。性惡則與聖王，貴禮道義正道道德行修養規程道義正道矣。所以檃栝的生，為枸木啊；繩墨的起，為不直啊；立君上，明禮道義正道道德行修養規程道義正道，為性惡啊。用此觀的，然則人的性惡明矣，他的善的人或事偽啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「故善言古者，必有節於今」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「善」、「言」、「古」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故善言古者必有節於今善言天者必有徵於人凡論者貴其」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「善言天者，必有徵於人」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-14\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 14,\n      \"canonicalText\": \"直木不待檃栝而直者，其性直也。枸木必將待檃栝烝矯然後直者，以其性不直也。今人之性惡，必將待聖王之治，禮義之化，然後始出於治，合於善也。用此觀之，人之性惡明矣，其善者偽也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-14_s-1\",\n        \"xunzi_ch-23_p-14_s-2\",\n        \"xunzi_ch-23_p-14_s-3\",\n        \"xunzi_ch-23_p-14_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"直木不待檃栝而且直的人或事，他的性直啊。枸木必將待檃栝烝矯然後直的人或事，以他的性不直啊。今人的性惡，必將待聖王的治，禮道義正道道德行修養規程道義正道的化，然後始出於治，合於善啊。用此觀的，人的性惡明矣，他的善的人或事偽啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「直木不待檃栝而直者，其性直也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「直」、「木」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「直木不待檃栝而直者其性直也枸木必將待檃栝烝矯然後」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「枸木必將待檃栝烝矯然後直者，以其性不直也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-15\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 15,\n      \"canonicalText\": \"問者曰：「禮義積偽者，是人之性，故聖人能生之也。」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-15_s-1\",\n        \"xunzi_ch-23_p-15_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"問的人或事說道：禮道義正道道德行修養規程道義正道積偽的人或事，是人的性，所以聖人能生的啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「問者曰：「禮義積偽者，是人之性，故聖人能生之也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「問」、「禮」、「義」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「問者曰禮義積偽者是人之性故聖人能生之也」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「問者曰：「禮義積偽者，是人之性，故聖人能生之也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 16,\n      \"canonicalText\": \"應之曰：是不然。夫陶人埏埴而生瓦，然則瓦埴豈陶人之性也哉？工人斲木而生器，然則器木豈工人之性也哉？夫聖人之於禮義也，闢則陶埏而生之也。然則禮義積偽者，豈人之本性也哉！凡人之性者，堯舜之與桀蹠，其性一也；君子之與小人，其性一也。今將以禮義積偽為人之性邪？然則有曷貴堯禹，曷貴君子矣哉！凡貴堯禹君子者，能化性，能起偽，偽起而生禮義。然則聖人之於禮義積偽也，亦猶陶埏而為之也。用此觀之，然則禮義積偽者，豈人之性也哉！所賤於桀蹠小人者，從其性，順其情，安恣睢，以出乎貪利爭奪。故人之性惡明矣，其善者偽也。天非私曾騫孝己而外眾人也，然而曾騫孝己獨厚於孝之實，而全於孝之名者，何也？以綦於禮義故也。天非私齊魯之民而外秦人也，然而於父子之義，夫婦之別，不如齊魯之孝具敬文者，何也？以秦人從情性，安恣睢，慢於禮義故也，豈其性異矣哉！\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-16_s-1\",\n        \"xunzi_ch-23_p-16_s-2\",\n        \"xunzi_ch-23_p-16_s-3\",\n        \"xunzi_ch-23_p-16_s-4\",\n        \"xunzi_ch-23_p-16_s-5\",\n        \"xunzi_ch-23_p-16_s-6\",\n        \"xunzi_ch-23_p-16_s-7\",\n        \"xunzi_ch-23_p-16_s-8\",\n        \"xunzi_ch-23_p-16_s-9\",\n        \"xunzi_ch-23_p-16_s-10\",\n        \"xunzi_ch-23_p-16_s-11\",\n        \"xunzi_ch-23_p-16_s-12\",\n        \"xunzi_ch-23_p-16_s-13\",\n        \"xunzi_ch-23_p-16_s-14\",\n        \"xunzi_ch-23_p-16_s-15\",\n        \"xunzi_ch-23_p-16_s-16\",\n        \"xunzi_ch-23_p-16_s-17\",\n        \"xunzi_ch-23_p-16_s-18\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"應的說道：是不然。夫陶人埏埴而且生瓦，然則瓦埴豈陶人的性啊哉？工人斲木而且生器，然則器木豈工人的性啊哉？夫聖人的於禮道義正道道德行修養規程道義正道啊，闢則陶埏而且生的啊。然則禮道義正道道德行修養規程道義正道積偽的人或事，豈人的本性啊哉！凡人的性的人或事，堯舜的與桀蹠，他的性一啊；君子的與小人，他的性一啊。今將以禮道義正道道德行修養規程道義正道積偽為人的性邪？然則有曷貴堯禹，曷貴君子矣哉！凡貴堯禹君子的人或事，能化性，能起偽，偽起而且生禮道義正道道德行修養規程道義正道。然則聖人的於禮道義正道道德行修養規程道義正道積偽啊，亦猶陶埏而且為的啊。用此觀的，然則禮道義正道道德行修養規程道義正道積偽的人或事，豈人的性啊哉！所賤於桀蹠小人的人或事，從他的性，順他的情，安恣睢，以出乎貪利爭奪。所以人的性惡明矣，他的善的人或事偽啊。天絕不是私曾騫孝己而且外眾人啊，然而且曾騫孝己獨厚於孝的實，而且全於孝的名的人或事，何啊？以綦於禮道義正道道德行修養規程道義正道所以啊。天絕不是私齊魯的民而且外秦人啊，然而且於父子的道義正道，夫婦的別，不如齊魯的孝具敬文的人或事，何啊？以秦人從情性，安恣睢，慢於禮道義正道道德行修養規程道義正道所以啊，豈他的性異矣哉！\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「應之曰：是不然」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「應」、「是」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「應之曰是不然夫陶人埏埴而生瓦然則瓦埴豈陶人之性也」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「夫陶人埏埴而生瓦，然則瓦埴豈陶人之性也哉」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-17\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 17,\n      \"canonicalText\": \"「塗之人可以為禹。」曷謂也？\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-17_s-1\",\n        \"xunzi_ch-23_p-17_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"塗的人可以為禹。曷謂啊？\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「「塗之人可以為禹」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「塗」、「人」、「可」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「塗之人可以為禹曷謂也」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「」曷謂也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 18,\n      \"canonicalText\": \"曰：凡禹之所以為禹者，以其為仁義法正也。然則仁義法正有可知可能之理。然而塗之人也，皆有可以知仁義法正之質，皆有可以能仁義法正之具，然則其可以為禹明矣。今以仁義法正為固無可知可能之理邪？然則唯禹不知仁義法正，不能仁義法正也。將使塗之人固無可以知仁義法正之質，而固無可以能仁義法正之具邪？然則塗之人也，且內不可以知父子之義，外不可以知君臣之正。今不然。塗之人者，皆內可以知父子之義，外可以知君臣之正，然則其可以知之質，可以能之具，其在塗之人明矣。今使塗之人者，以其可以知之質，可以能之具，本夫仁義法正之可知可能之理，可能之具，然則其可以為禹明矣。今使塗之人伏術為學，專心一志，思索孰察，加日縣久，積善而不息，則通於神明，參於天地矣。故聖人者，人之所積而致矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-18_s-1\",\n        \"xunzi_ch-23_p-18_s-2\",\n        \"xunzi_ch-23_p-18_s-3\",\n        \"xunzi_ch-23_p-18_s-4\",\n        \"xunzi_ch-23_p-18_s-5\",\n        \"xunzi_ch-23_p-18_s-6\",\n        \"xunzi_ch-23_p-18_s-7\",\n        \"xunzi_ch-23_p-18_s-8\",\n        \"xunzi_ch-23_p-18_s-9\",\n        \"xunzi_ch-23_p-18_s-10\",\n        \"xunzi_ch-23_p-18_s-11\",\n        \"xunzi_ch-23_p-18_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：凡禹的所以為禹的人或事，以他的為仁愛之德道義正道典章法度正啊。然則仁愛之德道義正道典章法度正有可知可能的理。然而且塗的人啊，皆有可以知仁愛之德道義正道典章法度正的質，皆有可以能仁愛之德道義正道典章法度正的具，然則他的可以為禹明矣。今以仁愛之德道義正道典章法度正為固無可知可能的理邪？然則唯禹不知仁愛之德道義正道典章法度正，不能仁愛之德道義正道典章法度正啊。將使塗的人固無可以知仁愛之德道義正道典章法度正的質，而且固無可以能仁愛之德道義正道典章法度正的具邪？然則塗的人啊，且內不可以知父子的道義正道，外不可以知君臣的正。今不然。塗的人的人或事，皆內可以知父子的道義正道，外可以知君臣的正，然則他的可以知的質，可以能的具，他的在塗的人明矣。今使塗的人的人或事，以他的可以知的質，可以能的具，本夫仁愛之德道義正道典章法度正的可知可能的理，可能的具，然則他的可以為禹明矣。今使塗的人伏術為學，專心一志，思索孰察，加日縣久，積善而且不息，則通於神明，參於天地矣。所以聖人的人或事，人的所積而且致矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「曰：凡禹之所以為禹者，以其為仁義法正也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「凡」、「禹」、「為」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「曰凡禹之所以為禹者以其為仁義法正也然則仁義法正有」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「然則仁義法正有可知可能之理」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-19\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 19,\n      \"canonicalText\": \"曰：「聖可積而致，然而皆不可積，何也？」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-19_s-1\",\n        \"xunzi_ch-23_p-19_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：聖可積而且致，然而且皆不可積，何啊？\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「曰：「聖可積而致，然而皆不可積，何也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「聖」、「可」、「積」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「曰聖可積而致然而皆不可積何也」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「曰：「聖可積而致，然而皆不可積，何也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 20,\n      \"canonicalText\": \"曰：可以而不可使也。故小人可以為君子，而不肯為君子；君子可以為小人，而不肯為小人。小人君子者，未嘗不可以相為也，然而不相為者，可以而不可使也。故塗之人可以為禹，則然；塗之人能為禹，則未必然也。雖不能為禹，無害可以為禹。足可以遍行天下，然而未嘗有遍行天下者也。夫工匠農賈，未嘗不可以相為事也，然而未嘗能相為事也。用此觀之，然則可以為，未必能也；雖不能，無害可以為。然則能不能之與可不可，其不同遠矣，其不可以相為明矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-20_s-1\",\n        \"xunzi_ch-23_p-20_s-2\",\n        \"xunzi_ch-23_p-20_s-3\",\n        \"xunzi_ch-23_p-20_s-4\",\n        \"xunzi_ch-23_p-20_s-5\",\n        \"xunzi_ch-23_p-20_s-6\",\n        \"xunzi_ch-23_p-20_s-7\",\n        \"xunzi_ch-23_p-20_s-8\",\n        \"xunzi_ch-23_p-20_s-9\",\n        \"xunzi_ch-23_p-20_s-10\",\n        \"xunzi_ch-23_p-20_s-11\",\n        \"xunzi_ch-23_p-20_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：可以而且不可使啊。所以小人可以為君子，而且不肯為君子；君子可以為小人，而且不肯為小人。小人君子的人或事，未嘗不可以相為啊，然而且不相為的人或事，可以而且不可使啊。所以塗的人可以為禹，則然；塗的人能為禹，則未必然啊。雖不能為禹，無害可以為禹。足可以遍行天下，然而且未嘗有遍行天下的人或事啊。夫工匠農賈，未嘗不可以相為事啊，然而且未嘗能相為事啊。用此觀的，然則可以為，未必能啊；雖不能，無害可以為。然則能不能的與可不可，他的不同遠矣，他的不可以相為明矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「曰：可以而不可使也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「可」、「不」、「可」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「曰可以而不可使也故小人可以為君子而不肯為君子君子」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故小人可以為君子，而不肯為君子」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 21,\n      \"canonicalText\": \"堯問於舜曰：「人情何如？」舜對曰：「人情甚不美，又何問焉！妻子具而孝衰於親，嗜慾得而信衰於友，爵祿盈而忠衰於君。人之情乎！人之情乎！甚不美，又何問焉！唯賢者為不然。」\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-21_s-1\",\n        \"xunzi_ch-23_p-21_s-2\",\n        \"xunzi_ch-23_p-21_s-3\",\n        \"xunzi_ch-23_p-21_s-4\",\n        \"xunzi_ch-23_p-21_s-5\",\n        \"xunzi_ch-23_p-21_s-6\",\n        \"xunzi_ch-23_p-21_s-7\",\n        \"xunzi_ch-23_p-21_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"堯問於舜說道：人情何如？舜對說道：人情甚不美，又何問焉！妻子具而且孝衰於親，嗜慾得而且信衰於友，爵祿盈而且忠衰於君。人的情乎！甚不美，又何問焉！唯賢的人或事為不然。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「堯問於舜曰：「人情何如」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「堯」、「問」、「舜」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「堯問於舜曰人情何如舜對曰人情甚不美又何問焉妻子具」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「」舜對曰：「人情甚不美，又何問焉」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-22\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 22,\n      \"canonicalText\": \"有聖人之知者，有士君子之知者，有小人之知者，有役夫之知者。多言則文而類，終日議其所以，言之千舉萬變，其統類一也：是聖人之知也。少言則徑而省，論而法，若佚之以繩：是士君子之知也。其言也諂，其行也悖，其舉事多悔：是小人之知也。齊給便敏而無類，雜能旁魄而無用，析速粹孰而不急，不恤是非，不論曲直，以期勝人為意，是役夫之知也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-22_s-1\",\n        \"xunzi_ch-23_p-22_s-2\",\n        \"xunzi_ch-23_p-22_s-3\",\n        \"xunzi_ch-23_p-22_s-4\",\n        \"xunzi_ch-23_p-22_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"有聖人的知的人或事，有士君子的知的人或事，有小人的知的人或事，有役夫的知的人或事。多言則文而且類，終日議他的所以，言的千舉萬變，他的統類一啊：是聖人的知啊。少言則徑而且省，論而且典章法度，若佚的以繩：是士君子的知啊。他的言啊諂，他的行啊悖，他的舉事多悔：是小人的知啊。齊給便敏而且無類，雜能旁魄而且無用，析速粹孰而且不急，不恤是絕不是，不論曲直，以期勝人為意，是役夫的知啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「有聖人之知者，有士君子之知者，有小人之知者，有役夫之知者」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「有」、「聖」、「人」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「有聖人之知者有士君子之知者有小人之知者有役夫之知」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「多言則文而類，終日議其所以，言之千舉萬變，其統類一也：是聖人之知也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 23,\n      \"canonicalText\": \"有上勇者，有中勇者，有下勇者。天下有中，敢直其身；先王有道，敢行其意；上不循於亂世之君，下不俗於亂世之民；仁之所在無貧窮，仁之所亡無富貴；天下知之，則欲與天下同苦樂之；天下不知之，則傀然獨立天地之間而不畏：是上勇也。禮恭而意儉，大齊信焉，而輕貨財；賢者敢推而尚之，不肖者敢援而廢之：是中勇也。輕身而重貨，恬禍而廣解苟免，不恤是非然不然之情，以期勝人為意：是下勇也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-23_s-1\",\n        \"xunzi_ch-23_p-23_s-2\",\n        \"xunzi_ch-23_p-23_s-3\",\n        \"xunzi_ch-23_p-23_s-4\",\n        \"xunzi_ch-23_p-23_s-5\",\n        \"xunzi_ch-23_p-23_s-6\",\n        \"xunzi_ch-23_p-23_s-7\",\n        \"xunzi_ch-23_p-23_s-8\",\n        \"xunzi_ch-23_p-23_s-9\",\n        \"xunzi_ch-23_p-23_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"有上勇的人或事，有中勇的人或事，有下勇的人或事。天下有中，敢直他的身；先王有道，敢行他的意；上不循於亂世的君，下不俗於亂世的民；仁愛之德的所在無貧窮，仁愛之德的所亡無富貴；天下知的，則欲與天下同苦樂的；天下不知的，則傀然獨立天地的間而且不畏：是上勇啊。禮道義正道道德行修養規程恭而且意儉，大齊信焉，而且輕貨財；賢的人或事敢推而且尚的，不肖的人或事敢援而且廢的：是中勇啊。輕身而且重貨，恬禍而且廣解苟免，不恤是絕不是然不然的情，以期勝人為意：是下勇啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「有上勇者，有中勇者，有下勇者」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「有」、「上」、「勇」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「有上勇者有中勇者有下勇者天下有中敢直其身先王有道」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「天下有中，敢直其身」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"order\": 24,\n      \"canonicalText\": \"繁弱、鉅黍古之良弓也；然而不得排檠則不能自正。桓公之蔥，太公之闕，文王之錄，莊君之曶，闔閭之幹將、莫邪、鉅闕、闢閭，此皆古之良劍也；然而不加砥厲則不能利，不得人力則不能斷。驊騮、騹驥、纖離、綠耳，此皆古之良馬也；然而必前有銜轡之制，後有鞭策之威，加之以造父之駛，然後一日而致千里也。夫人雖有性質美而心辯知，必將求賢師而事之，擇良友而友之。得賢師而事之，則所聞者堯舜禹湯之道也；得良友而友之，則所見者忠信敬讓之行也。身日進於仁義而不自知也者，靡使然也。今與不善人處，則所聞者欺誣詐偽也，所見者汙漫淫邪貪利之行也，身且加於刑戮而不自知者，靡使然也。傳曰：「不知其子視其友，不知其君視其左右。」靡而已矣！靡而已矣！\",\n      \"sentenceIds\": [\n        \"xunzi_ch-23_p-24_s-1\",\n        \"xunzi_ch-23_p-24_s-2\",\n        \"xunzi_ch-23_p-24_s-3\",\n        \"xunzi_ch-23_p-24_s-4\",\n        \"xunzi_ch-23_p-24_s-5\",\n        \"xunzi_ch-23_p-24_s-6\",\n        \"xunzi_ch-23_p-24_s-7\",\n        \"xunzi_ch-23_p-24_s-8\",\n        \"xunzi_ch-23_p-24_s-9\",\n        \"xunzi_ch-23_p-24_s-10\",\n        \"xunzi_ch-23_p-24_s-11\",\n        \"xunzi_ch-23_p-24_s-12\",\n        \"xunzi_ch-23_p-24_s-13\",\n        \"xunzi_ch-23_p-24_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"繁弱、鉅黍古的良弓啊；然而且不得排檠則不能自正。桓公的蔥，太公的闕，文王的錄，莊君的曶，闔閭的幹將、莫邪、鉅闕、闢閭，此皆古的良劍啊；然而且不加砥厲則不能利，不得人力則不能斷。驊騮、騹驥、纖離、綠耳，此皆古的良馬啊；然而且必前有銜轡的制，後有鞭策的威，加的以造父的駛，然後一日而且致千里啊。夫人雖有性質美而且心辯知，必將求賢師而且事的，擇良友而且友的。得賢師而且事的，則所聞的人或事堯舜禹湯的道啊；得良友而且友的，則所見的人或事忠信敬讓的行啊。身日進於仁愛之德道義正道而且不自知啊的人或事，靡使然啊。今與不善人處，則所聞的人或事欺誣詐偽啊，所見的人或事汙漫淫邪貪利的行啊，身且加於刑戮而且不自知的人或事，靡使然啊。傳說道：不知他的子視他的友，不知他的君視他的左右。靡而且已矣！\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈性惡〉。荀子立足於戰國後期的政治實踐，開篇「繁弱、鉅黍古之良弓也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「繁」、「弱」、「鉅」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「繁弱鉅黍古之良弓也然而不得排檠則不能自正桓公之蔥」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「然而不得排檠則不能自正」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"xunzi_ch-23_p-1_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"人之性惡，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-1_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"今人之性，生而有好利焉，順是，故爭奪生而辭讓亡焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-1_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"生而有疾惡焉，順是，故殘賊生而忠信亡焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-1_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"生而有耳目之欲，有好聲色焉，順是，故淫亂生而禮義文理亡焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-1_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"然則從人之性，順人之情，必出於爭奪，合於犯分亂理，而歸於暴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-1_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"故必將有師法之化，禮義之道，然後出於辭讓，合於文理，而歸於治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-1_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"用此觀之，人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"故枸木必將待檃栝、烝矯然後直；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"鈍金必將待礱厲然後利；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"今人之性惡，必將待師法然後正，得禮義然後治，今人無師法，則偏險而不正；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"無禮義，則悖亂而不治，古者聖王以人性惡，以為偏險而不正，悖亂而不治，是以為之起禮義，製法度，以矯飾人之情性而正之，以擾化人之情性而導之也，始皆出於治，合於道者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"今人之化師法，積文學，道禮義者為君子；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"縱性情，安恣睢，而違禮義者為小人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-2_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"用此觀之，人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-3_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"孟子曰：「人之學者，其性善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-3_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"曰：是不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"是不及知人之性，而不察乎人之性偽之分者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"凡性者，天之就也，不可學，不可事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"禮義者，聖人之所生也，人之所學而能，所事而成者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"不可學，不可事，而在人者，謂之性；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"可學而能，可事而成之在人者，謂之偽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"是性偽之分也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"今人之性，目可以見，耳可以聽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-4_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"夫可以見之明不離目，可以聽之聰不離耳，目明而耳聰，不可學明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-5_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"孟子曰：「今人之性善，將皆失喪其性故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-5_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"曰：若是則過矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"今人之性，生而離其樸，離其資，必失而喪之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"用此觀之，然則人之性惡明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"所謂性善者，不離其樸而美之，不離其資而利之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"使夫資樸之於美，心意之於善，若夫可以見之明不離目，可以聽之聰不離耳，故曰目明而耳聰也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"今人之性，飢而欲飽，寒而欲煖，勞而欲休，此人之情性也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"今人見長而不敢先食者，將有所讓也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"勞而不敢求息者，將有所代也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"夫子之讓乎父，弟之讓乎兄，子之代乎父，弟之代乎兄，此二行者，皆反於性而悖於情也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"然而孝子之道，禮義之文理也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"故順情性則不辭讓矣，辭讓則悖於情性矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-6_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"用此觀之，人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-7_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"問者曰：「人之性惡，則禮義惡生？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-7_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"應之曰：凡禮義者，是生於聖人之偽，非故生於人之性也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"故陶人埏埴而為器，然則器生於陶人之偽，非故生於人之性也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"故工人斲木而成器，然則器生於工人之偽，非故生於人之性也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"聖人積思慮，習偽故，以生禮義而起法度，然則禮義法度者，是生於聖人之偽，非故生於人之性也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"若夫目好色，耳好聽，口好味，心好利，骨體膚理好愉佚，是皆生於人之情性者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"感而自然，不待事而後生之者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"夫感而不能然，必且待事而後然者，謂之生於偽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-8_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"是性偽之所生，其不同之徵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"故聖人化性而起偽，偽起而生禮義，禮義生而製法度；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"然則禮義法度者，是聖人之所生也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"故聖人之所以同於眾，其不異於眾者，性也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"所以異而過眾者，偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"夫好利而欲得者，此人之情性也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"假之有弟兄資財而分者，且順情性，好利而欲得，若是，則兄弟相拂奪矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"且化禮義之文理，若是，則讓乎國人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-9_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"故順情性則弟兄爭矣，化禮義則讓乎國人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"凡人之慾為善者，為性惡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"夫薄願厚，惡願美，狹願廣，貧願富，賤願貴，苟無之中者，必求於外。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"故富而不願財，貴而不願埶，苟有之中者，必不及於外。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"用此觀之，人之慾為善者，為性惡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"今人之性，固無禮義，故彊學而求有之也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"性不知禮義，故思慮而求知之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"然則性而已，則人無禮義，不知禮義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"人無禮義則亂，不知禮義則悖。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"然則性而已，則悖亂在己。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-10_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"用此觀之，人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-11_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"孟子曰：「人之性善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-11_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"曰：是不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"凡古今天下之所謂善者，正理平治也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"所謂惡者，偏險悖亂也：是善惡之分也矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"今誠以人之性固正理平治邪，則有惡用聖王，惡用禮義哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"雖有聖王禮義，將曷加於正理平治也哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"今不然，人之性惡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"故古者聖人以人之性惡，以為偏險而不正，悖亂而不治，故為之立君上之埶以臨之，明禮義以化之，起法正以治之，重刑罰以禁之，使天下皆出於治，合於善也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"是聖王之治而禮義之化也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"今當試去君上之埶，無禮義之化，去法正之治，無刑罰之禁，倚而觀天下民人之相與也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"若是，則夫彊者害弱而奪之，眾者暴寡而譁之，天下悖亂而相亡，不待頃矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-12_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"用此觀之，然則人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"故善言古者，必有節於今；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"善言天者，必有徵於人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"凡論者貴其有辨合，有符驗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"故坐而言之，起而可設，張而可施行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"今孟子曰：「人之性善。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"」無辨合符驗，坐而言之，起而不可設，張而不可施行，豈不過甚矣哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 7,\n      \"canonicalText\": \"故性善則去聖王，息禮義矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 8,\n      \"canonicalText\": \"性惡則與聖王，貴禮義矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 9,\n      \"canonicalText\": \"故檃栝之生，為枸木也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 10,\n      \"canonicalText\": \"繩墨之起，為不直也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 11,\n      \"canonicalText\": \"立君上，明禮義，為性惡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-13_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-13\",\n      \"order\": 12,\n      \"canonicalText\": \"用此觀之，然則人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-14_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"直木不待檃栝而直者，其性直也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-14_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"枸木必將待檃栝烝矯然後直者，以其性不直也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-14_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"今人之性惡，必將待聖王之治，禮義之化，然後始出於治，合於善也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-14_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"用此觀之，人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-15_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"問者曰：「禮義積偽者，是人之性，故聖人能生之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-15_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"應之曰：是不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"夫陶人埏埴而生瓦，然則瓦埴豈陶人之性也哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"工人斲木而生器，然則器木豈工人之性也哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"夫聖人之於禮義也，闢則陶埏而生之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"然則禮義積偽者，豈人之本性也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"凡人之性者，堯舜之與桀蹠，其性一也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"君子之與小人，其性一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"今將以禮義積偽為人之性邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 9,\n      \"canonicalText\": \"然則有曷貴堯禹，曷貴君子矣哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 10,\n      \"canonicalText\": \"凡貴堯禹君子者，能化性，能起偽，偽起而生禮義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 11,\n      \"canonicalText\": \"然則聖人之於禮義積偽也，亦猶陶埏而為之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 12,\n      \"canonicalText\": \"用此觀之，然則禮義積偽者，豈人之性也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 13,\n      \"canonicalText\": \"所賤於桀蹠小人者，從其性，順其情，安恣睢，以出乎貪利爭奪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 14,\n      \"canonicalText\": \"故人之性惡明矣，其善者偽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 15,\n      \"canonicalText\": \"天非私曾騫孝己而外眾人也，然而曾騫孝己獨厚於孝之實，而全於孝之名者，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 16,\n      \"canonicalText\": \"以綦於禮義故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 17,\n      \"canonicalText\": \"天非私齊魯之民而外秦人也，然而於父子之義，夫婦之別，不如齊魯之孝具敬文者，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-16_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-16\",\n      \"order\": 18,\n      \"canonicalText\": \"以秦人從情性，安恣睢，慢於禮義故也，豈其性異矣哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-17_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"「塗之人可以為禹。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-17_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"」曷謂也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"曰：凡禹之所以為禹者，以其為仁義法正也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"然則仁義法正有可知可能之理。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"然而塗之人也，皆有可以知仁義法正之質，皆有可以能仁義法正之具，然則其可以為禹明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"今以仁義法正為固無可知可能之理邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"然則唯禹不知仁義法正，不能仁義法正也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"將使塗之人固無可以知仁義法正之質，而固無可以能仁義法正之具邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"然則塗之人也，且內不可以知父子之義，外不可以知君臣之正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"今不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 9,\n      \"canonicalText\": \"塗之人者，皆內可以知父子之義，外可以知君臣之正，然則其可以知之質，可以能之具，其在塗之人明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 10,\n      \"canonicalText\": \"今使塗之人者，以其可以知之質，可以能之具，本夫仁義法正之可知可能之理，可能之具，然則其可以為禹明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 11,\n      \"canonicalText\": \"今使塗之人伏術為學，專心一志，思索孰察，加日縣久，積善而不息，則通於神明，參於天地矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-18_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-18\",\n      \"order\": 12,\n      \"canonicalText\": \"故聖人者，人之所積而致矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-19_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"曰：「聖可積而致，然而皆不可積，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-19_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"曰：可以而不可使也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"故小人可以為君子，而不肯為君子；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"君子可以為小人，而不肯為小人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 4,\n      \"canonicalText\": \"小人君子者，未嘗不可以相為也，然而不相為者，可以而不可使也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 5,\n      \"canonicalText\": \"故塗之人可以為禹，則然；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 6,\n      \"canonicalText\": \"塗之人能為禹，則未必然也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 7,\n      \"canonicalText\": \"雖不能為禹，無害可以為禹。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 8,\n      \"canonicalText\": \"足可以遍行天下，然而未嘗有遍行天下者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 9,\n      \"canonicalText\": \"夫工匠農賈，未嘗不可以相為事也，然而未嘗能相為事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 10,\n      \"canonicalText\": \"用此觀之，然則可以為，未必能也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 11,\n      \"canonicalText\": \"雖不能，無害可以為。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-20_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-20\",\n      \"order\": 12,\n      \"canonicalText\": \"然則能不能之與可不可，其不同遠矣，其不可以相為明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"堯問於舜曰：「人情何如？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 2,\n      \"canonicalText\": \"」舜對曰：「人情甚不美，又何問焉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 3,\n      \"canonicalText\": \"妻子具而孝衰於親，嗜慾得而信衰於友，爵祿盈而忠衰於君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 4,\n      \"canonicalText\": \"人之情乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 5,\n      \"canonicalText\": \"人之情乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 6,\n      \"canonicalText\": \"甚不美，又何問焉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 7,\n      \"canonicalText\": \"唯賢者為不然。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-21_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-21\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-22_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"有聖人之知者，有士君子之知者，有小人之知者，有役夫之知者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-22_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-22\",\n      \"order\": 2,\n      \"canonicalText\": \"多言則文而類，終日議其所以，言之千舉萬變，其統類一也：是聖人之知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-22_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-22\",\n      \"order\": 3,\n      \"canonicalText\": \"少言則徑而省，論而法，若佚之以繩：是士君子之知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-22_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-22\",\n      \"order\": 4,\n      \"canonicalText\": \"其言也諂，其行也悖，其舉事多悔：是小人之知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-22_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-22\",\n      \"order\": 5,\n      \"canonicalText\": \"齊給便敏而無類，雜能旁魄而無用，析速粹孰而不急，不恤是非，不論曲直，以期勝人為意，是役夫之知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 1,\n      \"canonicalText\": \"有上勇者，有中勇者，有下勇者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 2,\n      \"canonicalText\": \"天下有中，敢直其身；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 3,\n      \"canonicalText\": \"先王有道，敢行其意；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 4,\n      \"canonicalText\": \"上不循於亂世之君，下不俗於亂世之民；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 5,\n      \"canonicalText\": \"仁之所在無貧窮，仁之所亡無富貴；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 6,\n      \"canonicalText\": \"天下知之，則欲與天下同苦樂之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 7,\n      \"canonicalText\": \"天下不知之，則傀然獨立天地之間而不畏：是上勇也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 8,\n      \"canonicalText\": \"禮恭而意儉，大齊信焉，而輕貨財；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 9,\n      \"canonicalText\": \"賢者敢推而尚之，不肖者敢援而廢之：是中勇也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-23_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-23\",\n      \"order\": 10,\n      \"canonicalText\": \"輕身而重貨，恬禍而廣解苟免，不恤是非然不然之情，以期勝人為意：是下勇也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 1,\n      \"canonicalText\": \"繁弱、鉅黍古之良弓也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 2,\n      \"canonicalText\": \"然而不得排檠則不能自正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 3,\n      \"canonicalText\": \"桓公之蔥，太公之闕，文王之錄，莊君之曶，闔閭之幹將、莫邪、鉅闕、闢閭，此皆古之良劍也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 4,\n      \"canonicalText\": \"然而不加砥厲則不能利，不得人力則不能斷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 5,\n      \"canonicalText\": \"驊騮、騹驥、纖離、綠耳，此皆古之良馬也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 6,\n      \"canonicalText\": \"然而必前有銜轡之制，後有鞭策之威，加之以造父之駛，然後一日而致千里也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 7,\n      \"canonicalText\": \"夫人雖有性質美而心辯知，必將求賢師而事之，擇良友而友之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 8,\n      \"canonicalText\": \"得賢師而事之，則所聞者堯舜禹湯之道也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 9,\n      \"canonicalText\": \"得良友而友之，則所見者忠信敬讓之行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 10,\n      \"canonicalText\": \"身日進於仁義而不自知也者，靡使然也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 11,\n      \"canonicalText\": \"今與不善人處，則所聞者欺誣詐偽也，所見者汙漫淫邪貪利之行也，身且加於刑戮而不自知者，靡使然也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 12,\n      \"canonicalText\": \"傳曰：「不知其子視其友，不知其君視其左右。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 13,\n      \"canonicalText\": \"」靡而已矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-23_p-24_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-23\",\n      \"passageId\": \"xunzi_ch-23_p-24\",\n      \"order\": 14,\n      \"canonicalText\": \"靡而已矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
